\begin{figure}[t]
  \centering
  \usetikzlibrary{positioning}
  \begin{tikzpicture}[every node/.style={font={\footnotesize}}]

    \node[style=rectangle,minimum width=14cm,text depth=4.3cm,text height=3mm,anchor=south,align=center,draw=black,text=black,fill=white] (largeBoxPeeling) at (4.5cm, 1cm) {~};
    \node[anchor=north east,align=right,text=black,draw=black,inner sep=0.25cm] (e) at (largeBoxPeeling.north east) {\it\cref{sec:peelingBipartite}:\\\it Bipartite Peeling};
    \node[align=center] (peelingDegree2) at (0.5cm, 5.25cm) {\cref{lem:peelingDegree2}:\\$p(d_1, \ldots, d_{n-1},2) = p(d_1,\ldots,d_{n-1})$};
    \node[align=center] (peelingDegree1) at (6cm, 5.25cm) {~\\~\\\cref{lem:peelingDegree1}:\\$p(\underbrace{1, \ldots, 1}_b, d_{b+1}, \ldots, d_{n}) \leq (7/8)^{b-1}$};
    \node[align=center] (nodeDegree1) at (6cm, 3.75cm) {\cref{lem:nodeDegree1}: $l \in \H\setminus\HProm$:\\$p(d_1, \ldots, d_{n/2}) \leq (\constantMaxC)^{n/2}$};
    \node[align=center] (peelingSeparate) at (0.5cm, 3.75cm) {\cref{lem:peelingSeparate}: Success\\probabilities can be separated};
    \node[align=center] (maxC) at (6cm, 1.75cm) {\cref{lem:maxC}: $l \in \H\setminus\HProm$\\satisfies $\|C(l)\| \ll (e/2)^{-n/2}$};

    \node[style=rectangle,minimum width=14cm,text depth=3.98cm,text height=3mm,anchor=north,align=center,draw=black,text=black,fill=white] (largeBoxConcentration) at ($(largeBoxPeeling.south)+(0, \the\pgflinewidth)$) {~};
    \node[anchor=north east,text=black,align=right,draw=black,inner sep=0.25cm] (e) at (largeBoxConcentration.north east) {\it\cref{s:concentrationBounds}:\\\it Concentration Bounds};
    \node[align=center] (upperLower) at (10cm, -2.75cm) {\cref{cor:upperLower}:\\$\hat Z-D \leq Z^* \leq \hat Z$};
    \node[align=center] (smallD) at (8.5cm, -1cm) {\cref{lem:smallD}:\\$\expect(D) \ll \expect(\hat Z)$};
    \node[align=center] (sConcentration) at (6cm, -1cm) {\cref{lem:sConcentration}: whp,\\$\hat Z \geq \expect(\hat Z)/2$};
    \node[align=center] (largeZ) at (6cm, -2.75cm) {\cref{lem:largeZ}: whp,\\$Z^* \geq \expect(\hat Z)/4$};
    \node[align=center] (largeZ2) at (4.0cm, 0.25cm) {\cref{lem:largeZ2}:\\$\expect(\hat Z) \geq 4/5 \cdot (e/2)^{-n/2}$};

    \node[style=rectangle,minimum width=14cm,text depth=1.5cm,text height=3mm,anchor=north,align=center,draw=black,text=black,fill=white] (largeBoxPool) at ($(largeBoxConcentration.south)+(0, \the\pgflinewidth)$) {~};
    \node[anchor=north east,align=right,text=black,draw=black,inner sep=0.25cm] (e) at (largeBoxPool.north east) {\it\cref{s:combining}: Combining\\with Pool $(r_i)_{i\in[k]}$};
    \node[align=center] (poolSuccessConditioned) at (0.5cm, -4.75cm) {\cref{lem:poolSuccessConditioned}:\\$\Pr\left(\textrm{success} \cond Z = z \right) > 1-(1-z)^k$};
    \node[align=center] (poolSuccess) at (6cm, -4.75cm) {\cref{thm:poolSuccess}:\\$\Pr\left(\textrm{success}\right)$ constant};

    \node[style=rectangle,minimum width=4.5cm,text depth=4.0cm,text height=6mm,anchor=west,align=center,draw=black,text=black,fill=white] (largeBoxPromisc) at (-2.5cm, 0.75cm) {~};
    \node[anchor=north east,align=right,text=black,draw=black,inner sep=0.25cm] (e) at (largeBoxPromisc.north east) {\it\cref{s:promiscuous}:\\\it Promiscuous HF};
    \node[align=center] (perfectBallsBins) at (-0.25cm, 1.5cm) {\cref{lem:perfectBallsBins}: $2n$ balls.\\$\Pr(n$ bins get $2$ balls each$)$};
    \node[align=center] (nodeDegree2) at (-0.25cm, 0.25cm) {\cref{lem:nodeDegree2}: whp, $<90\%$ of\\bins get $2$ balls each};
    \node[align=center] (eventPoolNodeDegree2) at (-0.25cm, -1.0cm) {\cref{lem:eventPoolNodeDegree2}: whp,\\$(l_i)_{i\in[k]} \cap \HProm = \emptyset$};

    \draw[->] (perfectBallsBins.south) -- (nodeDegree2.north);
    \draw[->] (nodeDegree2.east) -- (largeZ2.west);
    \draw[->] (nodeDegree2.south) -- (eventPoolNodeDegree2.north);
    \draw[->] (nodeDegree1.south) -- (maxC);
    \draw[->] (peelingDegree2.east) -- (peelingDegree1.west);
    \draw[->] ($(peelingDegree1.south)+(0,0.3)$) -- (nodeDegree1.north);
    \draw[->] (peelingSeparate.east) -- ($(maxC.north)-(0.2,0)$);
    \draw[->] (eventPoolNodeDegree2.east) -- (sConcentration.west);
    \draw[->] (maxC.south) -- (sConcentration.north);
    \draw[->] (maxC.south) -- (smallD.north);
    \draw[->] (smallD.south) -- ($(largeZ.north)+(0.2,0)$);
    \draw[->] (sConcentration.south) -- (largeZ);
    \draw[->] (upperLower.west) -- (largeZ.east);
    \draw[->] (poolSuccessConditioned.east) -- (poolSuccess.west);
    \draw[->] (largeZ.south) -- (poolSuccess.north);
    \draw[->] (largeZ2.south) -- ($(largeZ2.south)-(0,3)$) -- ($(poolSuccess.north)-(0.2,0)$);
    \draw[->] (largeZ2.east) -- ($(smallD.north)-(0.2,0)$);
    \draw[->] (largeZ2.south) -- ($(sConcentration.north)-(0.2,0)$);
  \end{tikzpicture}
  \caption{
    Illustration of the proof structure showing the success probability of sampling from hash function pools instead of independent hash functions.
    Variables $\hat Z$, $D$ and $Z^*$ are defined in \cref{s:concentrationBounds}.
    Functions $p$ and $q$ are defined in \cref{sec:peelingBipartite}.
  }
  \label{fig:proofStructure}
\end{figure}

